dict(title='Admiral Ackbar',type='Character',subtype='Rebel',original_set='Death Star II',set_icon='Death Star II',destiny='1',power='3',ability='3',printed_label='Force-Attuned',deploy='4',forfeit='7',icons=['Rebel','Pilot'],lore='Mon Calamari leader of Rebel fleet. Master military strategist. Early prisoner of Grand Moff Tarkin. Convinced his people to join the Alliance.',game_text='Deploys −2 to Home One. Adds 3 to power of any capital starship he pilots. Your capital starships deploy −1 to same system. Once per game, may take one Mon Calamari character or Admiral’s Order into hand from Reserve Deck; reshuffle.'),
dict(title='Artoo-Detoo In Red 5',type='Starship',subtype='Starfighter',model='X-wing',original_set='Third Anthology',set_icon='Premium',destiny='0 or 7',power='3',maneuver='4',hyperspeed='5',deploy='4',forfeit='5',icons=['Starship','Nav computer'],lore='R2-D2 saved Luke and his starfighter more times than the young pilot could count.',game_text='May add 1 pilot. Permanent astromech aboard is •R2-D2, who adds 2 to power, maneuver and hyperspeed. Luke of ability &lt; 5 deploys free aboard. Immune to attrition &lt; 5 when Luke piloting.'),
dict(title='B-wing Attack Squadron',type='Starship',subtype='Squadron',model='B-wing',original_set='Death Star II',set_icon='Death Star II',destiny='3',power='12',maneuver='2',hyperspeed='3',deploy='*',forfeit='12',icons=['Starship','Starship','Starship','Pilot','Pilot','Pilot','Nav computer','Nav computer','Nav computer'],uniqueness='Non-unique',lore='Utilizes dense formations on attack missions to concentrate firepower. This tactic is particularly effective in defeating deflector shields.',game_text='<nowiki>*</nowiki> Replaces 3 B-wings at one location (B-wings go to Used Pile). Permanent pilots provide total ability of 3. Each of its weapon destiny draws is +1.'),
dict(title='Bacta Tank',type='Effect',original_set='Hoth',set_icon='Hoth',destiny='3',icons=['Effect'],lore='Medical wonder invented centuries ago by the Vratix insectoid species. Gelatinous red bacta is suspended in a synthetic solution to create a healing bacterial medium.',game_text='Use 4 Force to deploy on your side of table. A non-droid character you just lost from table may be placed here. Holds one ‘patient’ at a time. During your deploy phase, may use X Force to bring ‘patient’ to hand, where X = deploy cost of ‘patient.’'),
dict(title='Capital Support',type="Admiral's Order",original_set='Death Star II',set_icon='Death Star II',destiny='6',icons=["Admiral's Order"],lore=None,game_text='Each pilot deploys −1 (or −2 if an admiral) aboard a capital starship. Each capital starship with a pilot character aboard is immune to attrition &lt; 4 (or adds 2 to immunity if starship already has immunity). During each of your control phases, opponent loses 1 Force for each battleground site your general controls that is related to a system you occupy.'),
