dict(title='Chief Chirpa',type='Character',subtype='Alien',original_set='Endor',set_icon='Endor',destiny='2',power='0',ability='2',deploy='3',forfeit='2',icons=['Alien'],lore='Leader of Wicket’s Ewok tribe for 42 seasons. Head of the Council of Elders. Decided to spare Han’s Rebels and join their fight against the Empire.',game_text='Deploys only on Endor. Power and forfeit +1 for each [[Light Force]] icon at same Endor site. Once during each of your deploy phases, may deploy one non-unique Ewok to same Endor site from Reserve Deck; reshuffle.'),
